Deno.test("secondary-dns model: get_primary_server rejects empty, '.' and '..' path arguments", () => {
  const args = { "primaryserver": "test-id-123" };
  const schema = model.methods.get_primary_server.arguments;
  assertEquals(schema.safeParse(args).success, true);
  for (const bad of ["", ".", ".."]) {
    assertEquals(
      schema.safeParse({ ...args, primaryserver: bad }).success,
      false,
      JSON.stringify(bad),
    );
  }
});

